class B { x: number; vx: number; m: number; constructor(x: number, vx: number, m: number) { this.x = x; this.vx = vx; this.m = m; } }
function main(): void {
  const b = [new B(1, 2, 3), new B(4, 5, 6)];
  let order = "";
  const idx = (i: number): number => { order += "i" + i; return i; };
  const val = (v: number): number => { order += "v" + v; return v; };
  b[idx(0)].vx -= val(1) * b[1].m;
  b[idx(1)].x += 2;
  b[0].m *= 3;
  b[1].m /= 2;
  const r = (b[0].vx -= 1);
  const arr = [1, 2, 3];
  arr[idx(2)] += val(10);
  arr[0] -= arr[1] * 2;
  console.log(b[0].x, b[0].vx, b[0].m, b[1].x, b[1].vx, b[1].m, r, arr.join(","), order);
  let e = 0;
  for (let step = 0; step < 1000; step++) {
    for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
      const d = b[i].x - b[j].x;
      b[i].vx -= d * 0.001;
      b[j].vx += d * 0.001;
    }
    e += b[0].vx;
  }
  console.log(b[0].vx.toFixed(6), b[1].vx.toFixed(6), e.toFixed(6));
}
